import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState
} from "react";

import Chart from "chart.js/auto";

import { marketIndices } from "./data";

import "./main.css";
import "./components.css";
import "./animations.css";
import "@fortawesome/fontawesome-free/css/all.min.css";


// ======================================================
// API CONFIGURATION
// ======================================================

const API_BASE_URL = "http://localhost:5000/api";

// Temporary user until login/authentication is added
const USER_ID = "testuser";


// ======================================================
// MAIN APP
// ======================================================

function App() {

  // ====================================================
  // STATE
  // ====================================================

  const [stocks, setStocks] = useState({});

  const [watchlist, setWatchlist] = useState([
    "RELIANCE",
    "TCS",
    "INFY"
  ]);

  const [filters, setFilters] = useState({
    search: "",
    sector: "",
    cap: ""
  });

  const [chartType, setChartType] = useState("line");

  const [theme, setTheme] = useState(
    () => localStorage.getItem("theme") || "dark"
  );

  const [marketStatus, setMarketStatus] =
    useState("LIVE");

  const [updating, setUpdating] =
    useState(false);

  const [loading, setLoading] =
    useState(true);

  const [selectedStock, setSelectedStock] =
    useState(null);

  const [portfolio, setPortfolio] = useState({
    userId: USER_ID,
    cashBalance: 100000,
    holdings: []
  });

  const [transactions, setTransactions] =
    useState([]);

  const [tradeLoading, setTradeLoading] =
    useState(false);

  const [message, setMessage] =
    useState("");

  const [messageType, setMessageType] =
    useState("success");


  // ====================================================
  // THEME
  // ====================================================

  useEffect(() => {

    document.body.className =
      theme === "light"
        ? "light-theme"
        : "dark-theme";

    const root = document.documentElement;

    if (theme === "light") {

      root.style.setProperty(
        "--bg-primary",
        "#ffffff"
      );

      root.style.setProperty(
        "--bg-secondary",
        "#f8f9fa"
      );

      root.style.setProperty(
        "--bg-tertiary",
        "#e9ecef"
      );

      root.style.setProperty(
        "--bg-panel",
        "#ffffff"
      );

      root.style.setProperty(
        "--text-primary",
        "#212529"
      );

      root.style.setProperty(
        "--text-secondary",
        "#6c757d"
      );

      root.style.setProperty(
        "--border-color",
        "#dee2e6"
      );

    } else {

      root.style.setProperty(
        "--bg-primary",
        "#0a0e1a"
      );

      root.style.setProperty(
        "--bg-secondary",
        "#1a1f35"
      );

      root.style.setProperty(
        "--bg-tertiary",
        "#242b42"
      );

      root.style.setProperty(
        "--bg-panel",
        "#1e2438"
      );

      root.style.setProperty(
        "--text-primary",
        "#e6e8ef"
      );

      root.style.setProperty(
        "--text-secondary",
        "#9ca3b4"
      );

      root.style.setProperty(
        "--border-color",
        "#2d3748"
      );
    }

  }, [theme]);


  // ====================================================
  // MESSAGE
  // ====================================================

  const showMessage = (
    text,
    type = "success"
  ) => {

    setMessage(text);
    setMessageType(type);

    setTimeout(() => {
      setMessage("");
    }, 3500);
  };


  // ====================================================
  // FETCH STOCKS
  // IMPORTANT:
  // NO [stocks] DEPENDENCY HERE
  // ====================================================

  const fetchStocks = useCallback(
    async () => {

      try {

        const response = await fetch(
          `${API_BASE_URL}/stocks`
        );

        if (!response.ok) {
          throw new Error(
            "Failed to fetch stocks"
          );
        }

        const data =
          await response.json();


        setStocks((previousStocks) => {

          const formattedStocks = {};


          data.forEach((stock) => {

            const oldStock =
              previousStocks[
                stock.symbol
              ];


            formattedStocks[
              stock.symbol
            ] = {

              symbol: stock.symbol,

              name: stock.name,

              price: Number(stock.price),

              change: Number(stock.change),

              changePercent:
                stock.changePercent,

              volume:
                Number(stock.volume || 0),

              marketCap:
                Number(
                  stock.marketCap || 0
                ),

              sector:
                stock.sector,

              exchange:
                stock.exchange,

              lastUpdated:
                stock.lastUpdated,


              history:
                oldStock?.history
                  ? [
                      ...oldStock.history.slice(
                        -49
                      ),

                      {
                        time:
                          new Date(
                            stock.lastUpdated
                          ).toLocaleTimeString(),

                        price:
                          Number(
                            stock.price
                          ),

                        volume:
                          Number(
                            stock.volume || 0
                          )
                      }
                    ]

                  : [
                      {
                        time:
                          new Date(
                            stock.lastUpdated
                          ).toLocaleTimeString(),

                        price:
                          Number(
                            stock.price
                          ),

                        volume:
                          Number(
                            stock.volume || 0
                          )
                      }
                    ]
            };

          });


          return formattedStocks;

        });


        setMarketStatus("LIVE");


      } catch (error) {

        console.error(
          "Stock fetch error:",
          error
        );

        setMarketStatus("ERROR");

        showMessage(
          "Unable to connect to the stock API.",
          "error"
        );

      }

    },
    []
  );


  // ====================================================
  // FETCH PORTFOLIO
  // ====================================================

  const fetchPortfolio =
    useCallback(async () => {

      try {

        const response =
          await fetch(
            `${API_BASE_URL}/portfolio/${USER_ID}`
          );


        if (!response.ok) {
          throw new Error(
            "Failed to fetch portfolio"
          );
        }


        const data =
          await response.json();


        setPortfolio(data);


      } catch (error) {

        console.error(
          "Portfolio fetch error:",
          error
        );

      }

    }, []);


  // ====================================================
  // FETCH TRANSACTIONS
  // ====================================================

  const fetchTransactions =
    useCallback(async () => {

      try {

        const response =
          await fetch(
            `${API_BASE_URL}/transactions/${USER_ID}`
          );


        if (!response.ok) {
          throw new Error(
            "Failed to fetch transactions"
          );
        }


        const data =
          await response.json();


        setTransactions(data);


      } catch (error) {

        console.error(
          "Transaction fetch error:",
          error
        );

      }

    }, []);


  // ====================================================
  // INITIAL DATA LOAD
  // ====================================================

  useEffect(() => {

    let mounted = true;


    const loadData =
      async () => {

        setLoading(true);


        await Promise.all([
          fetchStocks(),
          fetchPortfolio(),
          fetchTransactions()
        ]);


        if (mounted) {
          setLoading(false);
        }

      };


    loadData();


    return () => {
      mounted = false;
    };

  }, [
    fetchStocks,
    fetchPortfolio,
    fetchTransactions
  ]);


  // ====================================================
  // AUTO REFRESH
  // ====================================================

  useEffect(() => {

    const interval =
      setInterval(() => {

        fetchStocks();

      }, 180000);


    return () => {
      clearInterval(interval);
    };

  }, [fetchStocks]);


  // ====================================================
  // MANUAL REFRESH
  // ====================================================

  const refresh = async () => {

    if (updating) return;


    setUpdating(true);

    setMarketStatus("UPDATING");


    await fetchStocks();


    setUpdating(false);

    showMessage(
      "Stock data refreshed successfully."
    );

  };


  // ====================================================
  // WATCHLIST
  // ====================================================

  const addToWatchlist = (symbol) => {

    setWatchlist((previous) => {

      if (
        previous.includes(symbol)
      ) {
        return previous;
      }

      return [
        ...previous,
        symbol
      ];

    });

  };


  const removeFromWatchlist =
    (symbol) => {

      setWatchlist((previous) =>
        previous.filter(
          (item) => item !== symbol
        )
      );

    };


  // ====================================================
  // BUY STOCK
  // ====================================================

  const buyStock =
    async (
      symbol,
      quantity
    ) => {

      const amount =
        Number(quantity);


      if (
        !amount ||
        amount <= 0
      ) {

        showMessage(
          "Enter a valid quantity.",
          "error"
        );

        return;
      }


      setTradeLoading(true);


      try {

        const response =
          await fetch(
            `${API_BASE_URL}/transactions/buy`,
            {
              method: "POST",

              headers: {
                "Content-Type":
                  "application/json"
              },

              body: JSON.stringify({
                userId: USER_ID,
                symbol: symbol,
                quantity: amount
              })
            }
          );


        const data =
          await response.json();


        if (!response.ok) {

          throw new Error(
            data.message ||
              "Purchase failed"
          );

        }


        if (data.portfolio) {

          setPortfolio(
            data.portfolio
          );

        } else {

          await fetchPortfolio();

        }


        await fetchTransactions();


        showMessage(
          `Successfully bought ${amount} ${symbol} share(s).`
        );


      } catch (error) {

        console.error(
          "BUY error:",
          error
        );


        showMessage(
          error.message ||
            "Unable to buy stock.",
          "error"
        );


      } finally {

        setTradeLoading(false);

      }

    };


  // ====================================================
  // SELL STOCK
  // ====================================================

  const sellStock =
    async (
      symbol,
      quantity
    ) => {

      const amount =
        Number(quantity);


      if (
        !amount ||
        amount <= 0
      ) {

        showMessage(
          "Enter a valid quantity.",
          "error"
        );

        return;
      }


      setTradeLoading(true);


      try {

        const response =
          await fetch(
            `${API_BASE_URL}/transactions/sell`,
            {
              method: "POST",

              headers: {
                "Content-Type":
                  "application/json"
              },

              body: JSON.stringify({
                userId: USER_ID,
                symbol: symbol,
                quantity: amount
              })
            }
          );


        const data =
          await response.json();


        if (!response.ok) {

          throw new Error(
            data.message ||
              "Sale failed"
          );

        }


        if (data.portfolio) {

          setPortfolio(
            data.portfolio
          );

        } else {

          await fetchPortfolio();

        }


        await fetchTransactions();


        showMessage(
          `Successfully sold ${amount} ${symbol} share(s).`
        );


      } catch (error) {

        console.error(
          "SELL error:",
          error
        );


        showMessage(
          error.message ||
            "Unable to sell stock.",
          "error"
        );


      } finally {

        setTradeLoading(false);

      }

    };


  // ====================================================
  // FILTER STOCKS
  // ====================================================

  const filteredStocks =
    useMemo(() => {

      let list =
        Object.entries(stocks);


      const search =
        filters.search
          .toLowerCase()
          .trim();


      if (search) {

        list =
          list.filter(
            ([symbol, stock]) =>

              stock.name
                .toLowerCase()
                .includes(search) ||

              symbol
                .toLowerCase()
                .includes(search) ||

              stock.sector
                .toLowerCase()
                .includes(search)
          );

      }


      if (filters.sector) {

        list =
          list.filter(
            ([, stock]) =>
              stock.sector ===
              filters.sector
          );

      }


      if (filters.cap) {

        list =
          list.filter(
            ([, stock]) => {

              const cap =
                Number(
                  stock.marketCap || 0
                );


              if (
                filters.cap ===
                "large"
              ) {

                return (
                  cap >=
                  500000000000
                );

              }


              if (
                filters.cap ===
                "mid"
              ) {

                return (
                  cap >=
                    50000000000 &&
                  cap <
                    500000000000
                );

              }


              return (
                cap <
                50000000000
              );

            }
          );

      }


      return list;

    }, [
      stocks,
      filters
    ]);


  // ====================================================
  // MARKET STATS
  // ====================================================

  const stats =
    useMemo(() => {

      const values =
        Object.values(stocks);


      const total =
        values.length;


      const gainers =
        values.filter(
          (stock) =>
            stock.change > 0
        ).length;


      const losers =
        values.filter(
          (stock) =>
            stock.change < 0
        ).length;


      const averageVolume =
        total > 0
          ? values.reduce(
              (sum, stock) =>
                sum +
                Number(
                  stock.volume || 0
                ),
              0
            ) /
            total /
            1000000
          : 0;


      return {

        total,

        gainers,

        losers,

        avgVol:
          averageVolume.toFixed(1)

      };

    }, [stocks]);


  // ====================================================
  // PORTFOLIO VALUE
  // ====================================================

  const portfolioValue =
    useMemo(() => {

      return portfolio.holdings.reduce(
        (
          total,
          holding
        ) => {

          const stock =
            stocks[
              holding.symbol
            ];


          if (!stock) {
            return total;
          }


          return (
            total +
            stock.price *
              holding.quantity
          );

        },
        0
      );

    }, [
      portfolio,
      stocks
    ]);


  const totalPortfolioValue =
    portfolio.cashBalance +
    portfolioValue;


  // ====================================================
  // EXPORT CSV
  // ====================================================

  const exportData = () => {

    const rows = [

      [
        "Company",
        "Symbol",
        "Sector",
        "Price",
        "Change",
        "Change %",
        "Volume",
        "Market Cap",
        "Exchange"
      ]

    ];


    Object.values(stocks)
      .forEach((stock) => {

        rows.push([

          stock.name,

          stock.symbol,

          stock.sector,

          stock.price.toFixed(2),

          stock.change.toFixed(2),

          stock.changePercent,

          stock.volume,

          stock.marketCap,

          stock.exchange

        ]);

      });


    const csv =
      rows
        .map((row) =>
          row
            .map(
              (value) =>
                `"${String(
                  value
                ).replaceAll(
                  '"',
                  '""'
                )}"`
            )
            .join(",")
        )
        .join("\n");


    const blob =
      new Blob(
        [csv],
        {
          type:
            "text/csv;charset=utf-8;"
        }
      );


    const url =
      URL.createObjectURL(blob);


    const link =
      document.createElement("a");


    link.href = url;


    link.download =
      `techstock-data-${
        new Date()
          .toISOString()
          .split("T")[0]
      }.csv`;


    document.body.appendChild(link);

    link.click();

    document.body.removeChild(link);


    URL.revokeObjectURL(url);

  };


  // ====================================================
  // RENDER
  // ====================================================

  return (

    <div className="dashboard">


      {/* ============================================= */}
      {/* NOTIFICATION */}
      {/* ============================================= */}

      {message && (

        <div
          style={{
            position: "fixed",
            top: "80px",
            right: "25px",
            zIndex: 99999,
            padding:
              "14px 20px",
            borderRadius: "8px",
            background:
              messageType ===
              "error"
                ? "#ef4444"
                : "#10b981",
            color: "#ffffff",
            fontWeight: "600",
            boxShadow:
              "0 10px 30px rgba(0,0,0,.3)"
          }}
        >

          <i
            className={`fas ${
              messageType ===
              "error"
                ? "fa-exclamation-circle"
                : "fa-check-circle"
            }`}
            style={{
              marginRight: "8px"
            }}
          />

          {message}

        </div>

      )}


      {/* ============================================= */}
      {/* TOP NAVIGATION */}
      {/* ============================================= */}

      <nav className="topbar">

        <div className="nav-content">


          <div className="brand">

            <i
              className="fas fa-chart-line brand-icon"
            />

            <span className="brand-text">
              TechStock
            </span>

            <span className="brand-accent">
              PRO
            </span>

          </div>


          <div className="nav-controls">


            <div className="market-status">

              <div
                className={`status-dot ${
                  marketStatus ===
                  "ERROR"
                    ? ""
                    : "active"
                }`}
              />

              <span>
                {marketStatus}
              </span>

            </div>


            <button
              className="btn-icon"
              onClick={() => {

                const nextTheme =
                  theme === "dark"
                    ? "light"
                    : "dark";


                setTheme(
                  nextTheme
                );


                localStorage.setItem(
                  "theme",
                  nextTheme
                );

              }}
            >

              <i
                className={`fas ${
                  theme ===
                  "light"
                    ? "fa-moon"
                    : "fa-palette"
                }`}
              />

            </button>

          </div>

        </div>

      </nav>


      {/* ============================================= */}
      {/* MARKET TICKER */}
      {/* ============================================= */}

      <div className="market-strip">

        <div className="market-ticker">

          {marketIndices.map(
            (index) => (

              <div
                className="ticker-item"
                key={index.name}
              >

                <span className="ticker-name">
                  {index.name}
                </span>

                <span className="ticker-price">
                  {index.value.toLocaleString()}
                </span>

                <span
                  className={`ticker-change ${
                    index.change >=
                    0
                      ? "positive"
                      : "negative"
                  }`}
                >

                  {index.change >=
                  0
                    ? "▲"
                    : "▼"}

                  {" "}

                  {Math.abs(
                    index.change
                  )}

                </span>

              </div>

            )
          )}

        </div>

      </div>


      {/* ============================================= */}
      {/* MAIN GRID */}
      {/* ============================================= */}

      <div className="main-grid">


        {/* =========================================== */}
        {/* SIDEBAR */}
        {/* =========================================== */}

        <aside className="sidebar">


          {/* ========================================= */}
          {/* WATCHLIST */}
          {/* ========================================= */}

          <div className="panel watchlist-panel">

            <div className="panel-header">

              <h3>

                <i className="fas fa-star" />

                {" "}Watchlist

              </h3>


              <span className="value-badge">

                ₹
                {watchlist
                  .reduce(
                    (
                      sum,
                      symbol
                    ) =>
                      sum +
                      (
                        stocks[
                          symbol
                        ]?.price ||
                        0
                      ),
                    0
                  )
                  .toLocaleString(
                    undefined,
                    {
                      maximumFractionDigits:
                        0
                    }
                  )}

              </span>

            </div>


            <div className="panel-body">

              <div className="watchlist-items">


                {watchlist.length ===
                0 ? (

                  <div className="empty-state">

                    <i className="fas fa-star" />

                    <p>
                      Your watchlist is empty
                    </p>

                  </div>

                ) : (

                  watchlist.map(
                    (symbol) => {

                      const stock =
                        stocks[
                          symbol
                        ];


                      if (!stock) {
                        return null;
                      }


                      return (

                        <div
                          className="watchlist-item"
                          key={symbol}
                          onClick={() =>
                            setSelectedStock(
                              symbol
                            )
                          }
                        >

                          <div className="stock-info">

                            <h4>
                              {stock.name}
                            </h4>

                            <div className="stock-meta">

                              {stock.symbol}

                              {" • "}

                              {stock.sector}

                            </div>

                          </div>


                          <div className="stock-data">

                            <div className="stock-price">

                              ₹
                              {stock.price.toFixed(
                                2
                              )}

                            </div>


                            <div
                              className={`stock-change ${
                                stock.change >=
                                0
                                  ? "positive"
                                  : "negative"
                              }`}
                            >

                              {stock.change >=
                              0
                                ? "+"
                                : ""}

                              {stock.change.toFixed(
                                2
                              )}

                            </div>

                          </div>


                          <button
                            className="btn-remove"
                            onClick={(
                              event
                            ) => {

                              event.stopPropagation();

                              removeFromWatchlist(
                                symbol
                              );

                            }}
                          >

                            <i className="fas fa-times" />

                          </button>

                        </div>

                      );

                    }
                  )

                )}

              </div>

            </div>

          </div>


          {/* ========================================= */}
          {/* SEARCH */}
          {/* ========================================= */}

          <div className="panel search-panel">

            <div className="panel-header">

              <h3>

                <i className="fas fa-search" />

                {" "}Search

              </h3>

            </div>


            <div className="panel-body">

              <div className="search-container">

                <input
                  value={
                    filters.search
                  }
                  onChange={(
                    event
                  ) =>
                    setFilters(
                      (
                        previous
                      ) => ({
                        ...previous,
                        search:
                          event.target
                            .value
                      })
                    )
                  }
                  placeholder="Search stocks..."
                  className="search-input"
                />

                <i className="fas fa-search search-icon" />

              </div>


              <div className="filters">


                <select
                  value={
                    filters.sector
                  }
                  onChange={(
                    event
                  ) =>
                    setFilters(
                      (
                        previous
                      ) => ({
                        ...previous,
                        sector:
                          event.target
                            .value
                      })
                    )
                  }
                  className="filter-select"
                >

                  <option value="">
                    All Sectors
                  </option>


                  {[
                    ...new Set(
                      Object.values(
                        stocks
                      ).map(
                        (stock) =>
                          stock.sector
                      )
                    )
                  ].map(
                    (sector) => (

                      <option
                        key={sector}
