// ======================================================
// STOCK CHART
// ======================================================

function StockChart({
  name,
  data,
  company,
  type
}) {

  const canvasRef =
    useRef(null);


  useEffect(() => {

    if (
      !canvasRef.current ||
      !data
    ) {
      return;
    }


    const ctx =
      canvasRef.current.getContext(
        "2d"
      );


    const color =
      data.change >= 0
        ? "#10b981"
        : "#ef4444";


    let background =
      color + "20";


    if (
      type === "area"
    ) {

      const gradient =
        ctx.createLinearGradient(
          0,
          0,
          0,
          250
        );


      gradient.addColorStop(
        0,
        color + "40"
      );


      gradient.addColorStop(
        1,
        color + "00"
      );


      background =
        gradient;

    }


    const history =
      data.history?.length
        ? data.history
        : [
            {
              time:
                new Date().toLocaleTimeString(),

              price:
                data.price
            }
          ];


    const chart =
      new Chart(
        ctx,
        {

          type:
            type === "area"
              ? "line"
              : type,

          data: {

            labels:
              history.map(
                (item) =>
                  item.time
              ),

            datasets: [

              {

                label:
                  `${name} Price`,

                data:
                  history.map(
                    (item) =>
                      item.price
                  ),

                borderColor:
                  color,

                backgroundColor:
                  type === "bar"
                    ? color + "80"
                    : background,

                borderWidth:
                  type === "bar"
                    ? 0
                    : 2,

                fill:
                  type === "area",

                tension:
                  0.4,

                pointRadius:
                  type === "bar"
                    ? 0
                    : 1

              }

            ]

          },


          options: {

            responsive: true,

            maintainAspectRatio:
              false,


            plugins: {

              legend: {
                display:
                  false
              },

              tooltip: {
                mode:
                  "index",

                intersect:
                  false
              }

            },


            scales: {

              x: {

                grid: {
                  color:
                    "#2d3748"
                },

                ticks: {
                  color:
                    "#6b7280",

                  font: {
                    size: 10
                  }

                }

              },


              y: {

                beginAtZero:
                  false,

                grid: {
                  color:
                    "#2d3748"
                },

                ticks: {

                  color:
                    "#6b7280",

                  callback:
                    (value) =>
                      "₹" +
                      Number(
                        value
                      ).toFixed(0)

                }

              }

            }

          }

        }
      );


    return () => {
      chart.destroy();
    };


  }, [
    data,
    name,
    type
  ]);


  return (

    <div className="chart-card fade-in">


      <div className="chart-header">


        <div>

          <h4 className="chart-title">
            {name}
          </h4>


          <div className="chart-symbol">

            {company.symbol}

            {" • "}

            {company.sector}

          </div>

        </div>


        <div>

          <div className="chart-price">

            ₹
            {data.price.toFixed(
              2
            )}

          </div>


          <div
            className={`chart-change ${
              data.change >= 0
                ? "positive"
                : "negative"
            }`}
          >

            {data.change >= 0
              ? "+"
              : ""}

            {data.change.toFixed(
              2
            )}

            {" "}

            (
            {
              data.changePercent
            }
            )

          </div>

        </div>


      </div>


      <div className="chart-container">

        <canvas
          ref={canvasRef}
        />

      </div>


    </div>

  );
}


