                  data.change >=
                  0
                    ? "positive"
                    : "negative"
                }`}
              >

                {data.change >=
                0
                  ? "▲"
                  : "▼"}

                {" "}

                {data.change >=
                0
                  ? "+"
                  : ""}

                {data.change.toFixed(
                  2
                )}

                {" "}

                (
                {
                  data.changePercent
                }
                )

              </div>

            </div>

          </div>


          <div className="details-grid">


            {/* CHART */}

            <div className="chart-section">

              <h3>

                <i className="fas fa-chart-line" />

                {" "}Price Chart

              </h3>


              <div className="modal-chart-container">

                <ModalChart
