              <div className="metrics-grid">


                <Metric
                  label="Volume"
                  value={Number(
                    data.volume ||
                    0
                  ).toLocaleString()}
                />


                <Metric
                  label="Market Cap"
                  value={formatMarketCap(
                    data.marketCap
                  )}
                />


                <Metric
                  label="Sector"
                  value={
                    data.sector
                  }
                />


                <Metric
                  label="Exchange"
                  value={
                    data.exchange
                  }
                />


              </div>


              {/* TRADING */}

              <div
                style={{
