                  {data.symbol}

                </h3>


                <div
                  style={{
                    display:
                      "flex",

                    gap:
                      "10px",

                    alignItems:
                      "center",

                    marginTop:
                      "12px",

                    flexWrap:
                      "wrap"
                  }}
                >


                  <input
