                      padding:
                        "10px",

                      borderRadius:
                        "6px",

                      border:
                        "1px solid var(--border-color)",

                      background:
                        "var(--bg-secondary)",

                      color:
                        "var(--text-primary)"
                    }}
                  />


                  {/* BUY */}

                  <button
                    className="btn-primary"
                    disabled={
                      tradeLoading
                    }
                    onClick={() =>
                      onBuy(
                        data.symbol,
                        quantity
                      )
                    }
                  >

                    <i className="fas fa-shopping-cart" />

                    {" "}

                    {tradeLoading
                      ? "Processing..."
                      : "BUY"}

                  </button>


                  {/* SELL */}

                  <button
                    className="btn-secondary"
                    disabled={
                      tradeLoading ||
                      !holding ||
                      holding.quantity <
                        quantity
                    }
                    onClick={() =>
                      onSell(
                        data.symbol,
                        quantity
                      )
                    }
                  >

                    <i className="fas fa-hand-holding-usd" />

                    {" "}SELL

                  </button>


                </div>


                <div
                  style={{
                    marginTop:
                      "12px",

                    fontSize:
                      "13px",

                    color:
                      "var(--text-secondary)"
                  }}
