                    className={`fas ${
                      inWatchlist
                        ? "fa-star"
                        : "fa-plus"
                    }`}
                  />

                  {" "}

                  {inWatchlist
                    ? "Remove from Watchlist"
                    : "Add to Watchlist"}

                </button>


              </div>


            </div>


          </div>


        </div>


      </div>


    </div>

  );
}


